import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
n=a.read('_notes.json');n['controls'].extend(a.read('_grammar_probes.json')['controls'])
def ev(p,*rs):
 p='pfp/domain/mssn_research/'+p;return {'path':p,'sha256':a.row(p)['sha256'],'lines':[list(x) for x in rs]}
rows=[
(97,'Packet atom factory bypasses its wire admission','Packet.atom(z,stage1) validates as Certificate although from_wire(<z>,stage1) refuses the inactive glyph. validate only round-trips and checks declared stage; it does not rerun AST admission or semantic arity.',[ev('packets/entities.py',(72,84),(154,169)),ev('packets/parser.py',(102,123))],[119]),
(98,'Quantifier budget trusts declared alternation count','A polarity mask with14 switches passes when alternation_count=0. Two variables each bounded10 pass step_budget10 despite100 Cartesian assignments. Per-variable bounds alone do not implement an evaluation budget or enforce mask consistency.',[ev('grammar/quantification.py',(91,99)),ev('grammar/quantifier_policies.py',(26,51))],[120]),
(99,'Phi4 dimension refusal is bypassed by eager helper evaluation','An empty dual vector triggers IndexError in _check_dual_cycle before the earlier dimension-error Result is returned, because all helper calls in checks tuple evaluate eagerly. A valid exact unit-objective certificate passes; the issue is malformed-input handling, not a demonstrated feasible false optimum.',[ev('grammar/quantifier_policies.py',(70,78),(100,123))],[121]),
(100,'Pending master horizon can exert terminal authority without receipt','A pending proposal with CertifiedTerminal authority and no receipt passes. Receipt-less path returnsOk unless requested green, and pending receipts also lack the red/green authority restrictions. This breaks the claimed proposal non-authority boundary.',[ev('grammar/authority_policies.py',(30,52),(64,100))],[122]),
(101,'Ind-object check omits target and relation preservation','A source generator maps to nonexistent target with no target stage record and an unverified text witness, yet passes. Source records are optional and relation_set never checked. Forward/injective labels do not prove a conservative presentation morphism or filtered diagram.',[ev('grammar/authority_policies.py',(108,166))],[123]),
(102,'Hodge checker ignores declared inner products','A valid Euclidean decomposition with exact=(1,0),coexact=(0,1) passes despite supplied positive-definite M1=[[2,1],[1,2]], for which their weighted inner product is1. All three metric matrices are ignored; weighted adjoints and complex nilpotence are unverified.',[ev('grammar/authority.py',(358,375)),ev('grammar/authority_policies.py',(226,247),(327,358))],[124]),
(103,'Regge checker accepts absent geometry and nonsymmetric Gram','Empty simplices/hinges with supplied negative determinant and closure=True pass without any rotation matrices. Optional [[1,100],[0,1]] Gram also passes positive leading minors though x=(1,-1) has xTGx=-98; symmetry and4D shape are missing. No exact holonomy or length-to-Gram binding is performed.',[ev('grammar/spectral_policies.py',(97,152))],[125]),
(104,'Zeta exactness check accepts floating coefficients','Coefficients(1,0.5), no traces and no transfer matrix pass with the default exactness flag. Only constant normalization/fence/flag are checked, so exact integer polynomial preservation and spectral correspondence are not established.',[ev('grammar/spectral_geometry.py',(62,79)),ev('grammar/spectral_policies.py',(24,53))],[126]),
(105,'Peak joining verifies string continuity without rewrite validity','Invented rule names/redex locations and unrelated peak apex pass when path endpoints meet. No ruleset/presentation replay or apex-to-branch evidence is checked; this supports endpoint consistency rather than semantic local confluence.',[ev('grammar/rewriting_policies.py',(32,91)),ev('grammar/entities.py',(308,322))],[127]),
(106,'DDA proof policy trusts a default true flag','A made-up transition with empty context/receipts, negative declared cost and default has_host_proof=True passes. The checker verifies only truthiness, parent digest length and positivebudget; no host proof, hash or transition replay occurs.',[ev('grammar/rewriting.py',(206,234)),ev('grammar/rewriting_policies.py',(98,120))],[128]),
(107,'Grammar frontier does not bind emissions or parser transitions','Stage1 frontier accepts emitted z and invented parser-state label when rational probabilities normalize. The arithmetic checks are useful but evaluate_frontier delegates without consulting active alphabet or parsing transitions; grammar licensing prose exceeds this boundary.',[ev('grammar/entities.py',(81,183),(275,282))],[129]),
(108,'Unsupported finite lift goal raises rather than refuses','Stage0 with DIRECTED_CYCLE_THREE raises ValueError despite public Result return contract. Supported stage0 irreflexive replay and forged-digest refusal both work; the limitation is the unhandled stage/goal cross-product.',[ev('grammar/lift_policies.py',(120,149),(208,230),(257,272))],[130]),
(109,'Accepted down-map can break edge involution','A four-edge involution with pairs a-b,c-d projects a,c to x, b to y,d to z. With no protected state pairs the down-map accepts, but its resulting reversal map fails involution. Preserving declared state distinctions does not preserve edge algebra.',[ev('grammar/entities.py',(502,525),(591,622))],[131])]
for num,title,st,es,ids in rows:n['findings'].append({'id':f'PFPDOMAIN-F{num:03}','title':title,'statement':st,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':[f'PFPDOMAIN-C{i:03}' for i in ids],'status':'confirmed_bounded_source_and_probe','limits':'Direct read-vetted domain policies on synthetic bounded values. No claim about external host repair, physical correctness or native equivalence.'})
for ident,title,st,es in [
('CL23','Finite lift certificates preserve explicit admissions','The finite lift owner enumerates the declared singleton/two-point relation spaces and recomputes count, obstruction, canonical target witness and digest. Bare assertion admits a singleton self-relation; irreflexivity and three distinct vertices are additional predicates. This is useful replayable finite necessity relative to supplied goals, not a derivation of those goals or an arbitrary Genesis tower.',[ev('grammar/lift_policies.py',(86,205),(208,291),(329,361))]),
('CL24','Exact arithmetic mechanisms remain useful within scoped contracts','Phi4 checks primal residual, dual cycle/capacity and zero exact Fraction gap, which certifies weighted-L1 optimality for admitted dimensions and nonnegative weights. BQNF repair recomputes omega=d0 alpha; frontier conditioning recomputes rational normalization. These reusable finite checks require source/representation/observation binding separately, and higher-stage physical labels do not supply it.',[ev('grammar/quantifier_policies.py',(54,155)),ev('grammar/rewriting_policies.py',(170,209)),ev('grammar/entities.py',(81,183))])]:n['claims'].append({'id':'PFPDOMAIN-'+ident,'title':title,'statement':st,'evidence':[e['path'] for e in es],'source_evidence':es,'status':'bounded_source_and_control_assessment'})
a.write('_notes.json',n);a.report()
